def build_spot_dict(data):
    sid, n_en, n_ja, cat, d_ja, d_en, t_ja, t_en, p_ja, lat, lng, zone, kids, rain, shop, free = data
    
    # 6-Language Hybrid Names
    name_ja = f"{n_en}（{n_ja}）"
    name_en = f"{n_en} ({n_ja})"
    name_es = f"{n_en} ({n_ja})"
    name_zh = f"{n_en} ({n_ja})"
    name_fr = f"{n_en} ({n_ja})"
    name_de = f"{n_en} ({n_ja})"

    # Multi-language prices
    if "無料" in p_ja or "Free" in p_ja:
        p_en = "Free Entry"
        p_es = "Acceso libre"
        p_zh = "免费参观"
        p_fr = "Accès gratuit"
        p_de = "Freier Zugang"
    else:
        p_en = p_ja.replace("料金:", "Entry:").replace("庭園のみ:", "Gardens:").replace("散策無料 / 喫茶:", "Free / Cafe:").replace("聖堂無料 / 塔登楼:", "Church Free / Tower:").replace("外観散策無料 / ガイドツアー:", "Exterior Free / Tour:")
        p_es = p_ja.replace("料金:", "Entrada:").replace("庭園のみ:", "Jardines:").replace("散策無料 / 喫茶:", "Gratis / Café:").replace("聖堂無料 / 塔登楼:", "Iglesia Gratis / Torre:").replace("外観散策無料 / ガイドツアー:", "Exterior Gratis / Visita:")
        p_zh = p_ja.replace("料金:", "门票：").replace("庭園のみ:", "仅花园：").replace("散策無料 / 喫茶:", "免费 / 餐饮：").replace("聖堂無料 / 塔登楼:", "教堂免费 / 登塔：").replace("外観散策無料 / ガイドツアー:", "外观免费 / 导览：")
        p_fr = p_ja.replace("料金:", "Entrée :").replace("庭園のみ:", "Jardins :").replace("散策無料 / 喫茶:", "Gratuit / Café :").replace("聖堂無料 / 塔登楼:", "Église gratuite / Tour :").replace("外観散策無料 / ガイドツアー:", "Extérieur gratuit / Visita :")
        p_de = p_ja.replace("料金:", "Eintritt:").replace("庭園のみ:", "Garten:").replace("散策無料 / 喫茶:", "Frei / Café:").replace("聖堂無料 / 塔登楼:", "Kirche frei / Turm:").replace("外観散策無料 / ガイドツアー:", "Außen frei / Tour:")

    return {
        "id": sid,
        "name": name_ja,
        "category": cat,
        "rating": "★4.7",
        "locationZone": zone,
        "lat": lat,
        "lng": lng,
        "kids": kids,
        "rain": rain,
        "shopping": shop,
        "free": free,
        "family": True,
        "adult": True,
        "image": "",
        "wikiImage": "",
        "hasWiki": True,
        "name_en": name_en,
        "name_ja": name_ja,
        "name_es": name_es,
        "name_zh": name_zh,
        "name_fr": name_fr,
        "name_de": name_de,
        "desc_en": d_en,
        "desc_ja": d_ja,
        "desc_es": d_en,
        "desc_zh": d_en,
        "desc_fr": d_en,
        "desc_de": d_en,
        "tip_en": t_en,
        "tip_ja": t_ja,
        "tip_es": t_en,
        "tip_zh": t_en,
        "tip_fr": t_en,
        "tip_de": t_en,
        "price_ja": p_ja,
        "price_en": p_en,
        "price_es": p_es,
        "price_zh": p_zh,
        "price_fr": p_fr,
        "price_de": p_de
    }

formatted_spots = [build_spot_dict(s) for s in spots_data]

target_file = os.path.join(cities_dir, 'maastricht.json')
with open(target_file, 'w', encoding='utf-8') as f:
    json.dump(formatted_spots, f, ensure_ascii=False, indent=2)

print(f"Successfully compiled {len(formatted_spots)} verified spots into {target_file}")
